import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.C-zpCNjM.js";var i=JSON.parse(`{"title":"URL Open","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/field-types/url-open.md","filePath":"documentation/field-types/url-open.md","lastUpdated":1791360312000}`),a={name:`documentation/field-types/url-open.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="url-open" tabindex="-1">URL Open <a class="header-anchor" href="#url-open" aria-label="Permalink to “URL Open”">​</a></h1><p>The <strong>URL Open</strong> field type navigates the current browser tab to a target web address.</p><h2 id="field-configuration" tabindex="-1">Field Configuration <a class="header-anchor" href="#field-configuration" aria-label="Permalink to “Field Configuration”">​</a></h2><table tabindex="0"><thead><tr><th>Field Option</th><th>Required</th><th>Description</th><th>Example Values</th></tr></thead><tbody><tr><td><strong>Default Value</strong> / <strong>Field Value</strong></td><td>Yes</td><td>Target URL to open in the active tab. Supports static URLs, Excel variables, and location variables.</td><td><code>https://example.com/login</code><br><code>https://example.com/item/{$productId$}</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">No Extra Configuration Required</p><p>The <strong>URL Open</strong> action navigates immediately upon execution. Simply define the destination address in the field&#39;s <strong>Default Value</strong> or map it to an <strong>Excel (.xlsx)</strong> column.</p></div><hr><h2 id="setting-target-url" tabindex="-1">Setting the Target URL <a class="header-anchor" href="#setting-target-url" aria-label="Permalink to “Setting the Target URL”">​</a></h2><h3 id="_1-static-url" tabindex="-1">1. Static URL <a class="header-anchor" href="#_1-static-url" aria-label="Permalink to “1. Static URL”">​</a></h3><p>Enter a fixed web address directly in the <strong>Default Value</strong> field:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://example.com/dashboard</span></span></code></pre></div><h3 id="_2-dynamic-url-from-excel-data" tabindex="-1">2. Dynamic URL from Excel Data <a class="header-anchor" href="#_2-dynamic-url-from-excel-data" aria-label="Permalink to “2. Dynamic URL from Excel Data”">​</a></h3><p>Map the URL or URL parameters to Excel column names using <code>{$columnName$}</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://example.com/products/{$productId$}</span></span></code></pre></div><h3 id="_3-using-page-location-variables" tabindex="-1">3. Using Page Location Variables <a class="header-anchor" href="#_3-using-page-location-variables" aria-label="Permalink to “3. Using Page Location Variables”">​</a></h3><p>Combine destination URLs with built-in location variables from the current page:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Example Output</th></tr></thead><tbody><tr><td><code>{$PAGE_URL$}</code></td><td>Current full URL</td><td><code>https://example.com/page?id=123</code></td></tr><tr><td><code>{$PAGE_HOSTNAME$}</code></td><td>Current domain/hostname</td><td><code>example.com</code></td></tr><tr><td><code>{$PAGE_PATHNAME$}</code></td><td>Current URL path</td><td><code>/products/item</code></td></tr><tr><td><code>{$PAGE_SEARCH$}</code></td><td>Current URL query parameters</td><td><code>?id=123</code></td></tr><tr><td><code>{$PAGE_HASH$}</code></td><td>Current URL hash fragment</td><td><code>#section</code></td></tr></tbody></table><p><strong>Example with Referrer:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://destination.com/portal?ref={$PAGE_HOSTNAME$}&amp;redirect={$PAGE_PATHNAME$}</span></span></code></pre></div><hr><h2 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to “Important Notes”">​</a></h2><ul><li><strong>Active Tab Navigation</strong>: Opens the URL in the <strong>current active tab</strong>, navigating away from the existing page.</li><li><strong>Workflow Continuity</strong>: Subsequent form fields in the execution queue will run against the newly loaded page.</li><li><strong>New Tab / Window Navigation</strong>: To open web pages without leaving the current tab, use <a href="/documentation/field-types/browser-actions.html#open-a-new-tab">Open a new Tab</a> or <a href="/documentation/field-types/browser-actions.html#open-a-new-window">Open a new Window</a>.</li></ul><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/variable.html#page-location-variable">Page Location Variables</a> — Full list of predefined location variables</li><li><img src="/svg/browser.svg" class="doc-icon"> <a href="/documentation/field-types/url-matching.html">URL Matching</a> — Trigger forms by matching URL patterns</li><li><img src="/svg/browser.svg" class="doc-icon"> <a href="/documentation/field-types/browser-actions.html">Browser Actions</a> — Tab and window automation controls</li><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template</a> — Excel (.xlsx) template structure</li></ul>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};